fn is_sorted(v: &Vec[Int]) -> Bool {
  for i in 0..v.len()-1 {
    if v[i] > v[i+1] { return false; }
  }
  return true;
}

fn merge(a: &Vec[Int], b: &Vec[Int]) -> Vec[Int]
  requires: is_sorted(a);
  requires: is_sorted(b);
{
  var result = Vec[Int]();
  var i = 0; var j = 0;
  while i < a.len() || j < b.len() {
    assert(i <= a.len() && j <= b.len());
    if j >= b.len() || (i < a.len() && a[i] <= b[j]) {
      result.push(a[i]); i = i + 1;
    } else {
      result.push(b[j]); j = j + 1;
    }
  }
  assert(result.len() == a.len() + b.len());
  return result;
}

fn main() -> Int {
  let x = Vec[Int](); x.push(1); x.push(3); x.push(5);
  let y = Vec[Int](); y.push(2); y.push(4); y.push(6);
  let m = merge(&x, &y);
  return m.len();
}
